def hamiltonian_path(graph: list[list[int]], start_node: int, end_node: int) -> list[int] | None:
    """
    Finds a Hamiltonian path from start_node to end_node.
    Returns the path if it exists, otherwise returns None.
    """
    path = [-1] * len(graph)
    path[0] = start_node

    def is_valid_transition(graph: list[list[int]], v: int, pos: int, path: list[int]) -> bool:
        # Check if this vertex is an adjacent vertex of the previously added vertex.
        if graph[path[pos - 1]][v] == 0:
            return False

        # Check if the vertex has already been included.
        if v in path[:pos]:
            return False

        return True

    def util_hamiltonian_path(graph: list[list[int]], path: list[int], pos: int) -> bool:
        # Base case: If all vertices are included and last vertex is end_node
        if pos == len(graph):
            return path[pos - 1] == end_node

        # Try different vertices as a next candidate for the Hamiltonian path.
        for v in range(len(graph)):
            if is_valid_transition(graph, v, pos, path):
                path[pos] = v
                if util_hamiltonian_path(graph, path, pos + 1):
                    return True
                path[pos] = -1
        return False

    if util_hamiltonian_path(graph, path, 1):
        return path

    return None
